	}
	uniqueKeyArgs := make([]interface{}, 0, b.uniqueKeyColumns.Len())
	for _, column := range b.uniqueKeyColumns.Columns() {
		tableOrdinal := b.tableColumns.Ordinals[column.Name]
		arg := column.convertArg(args[tableOrdinal])
